"""Fine-grained reading aids. All argument outlines are editorial reconstructions."""
def add_philosophy_guides(data):
 rows={
 'knowledge': dict(title='从“我相信”到“我有理由知道”',owner='以柏拉图的知识问题为线索',terms=[('意见','对事物的判断；在所讨论的对话中，意见与知识的对象、根据及稳定性有别，不能简单理解成胡说。'),('认识根据','让一项判断值得接受的理由、证据或说明；不同作者承认的根据并不相同。'),('洞穴寓言','《理想国》中的教育与认识图像，需要联系上下文解释，不能直接当成一个独立的实验报告。')],steps=[('辨别情形','一个人可能偶然判断正确，因此只问结论对不对，还不足以解释他是否知道。'),('追问根据','需要进一步说明判断凭什么成立，以及这些理由是否能经受反例和追问。'),('检验对象','柏拉图还追问知识所指向的对象是否具有稳定性，这与现代只分析信念的方式不同。'),('留下难点','怎样认识变化世界，以及不同对话中的回答是否一致，仍须逐篇检查。')],compare=[('柏拉图','区分知识与意见，追问可知对象和根据。','不同对话不能压成一份固定定义。'),('亚里士多德','从感觉、经验推进到知道原因及论证。','不是只积累感觉材料就自然得到科学。'),('笛卡尔','借方法怀疑追问确定的认识起点。','问题环境与古代对话不同，不能直接等同。')]),
 'forms': dict(title='共同性质是否必须与个物分离？',owner='围绕柏拉图及亚里士多德的争点作对读',terms=[('理念／形式','两位作者及不同译本的用法需分别读；不能因中文都译为形式，就假定它们在实在中的地位相同。'),('实体','亚里士多德用来讨论什么在首要意义上存在的核心概念，不只是有重量的物块。'),('质料','在某一层次分析中可以接受形式的方面；不应直接套成现代物理学的物质概念。')],steps=[('提出需要','许多个物可以被同样认识和称谓，因而需要解释其共同性。'),('给出方案','一种路径诉诸共同的可知形式，另一种强调在具体事物中理解形式与质料。'),('检查分离','若形式独立于个物，它如何解释个物？若不分离，普遍知识如何成立？'),('拒绝速断','分歧不能只归结为天上或地下的两个姿态；必须回到具体文本的论证。')],compare=[('柏拉图','一些对话以理念解释可知性和共同性质。','作者也让对话检验理念论自身的困难。'),('亚里士多德','批评分离形式，并分析实体和形式。','批评不等于拒绝一切普遍认识。'),('后世共相论者','重组共同性质、概念和个体的问题。','接受古代资源不表示各家答案相同。')]),
 'causes': dict(title='同一对象为何需要多层说明？',owner='以亚里士多德对人造物的说明为入门例子',terms=[('四因','质料、形式、动力、目的等不同的说明方向；这里的因不只指时间上先发生的事件。'),('潜能','某个对象在相应条件下具有的特定能力，不是没有限制的任意可能。'),('现实／实现','某种能力已在起作用或某种形式已实现；不是简单等同于“现实生活”这一日常用法。')],steps=[('选择实例','先用一件有材料、形态、制作过程及用途的人造物来厘清不同问题。'),('分开回答','材料是什么与谁使它形成，并不是同一句为什么；回答一个不等于回答全部。'),('分析变化','潜能与现实用于解释相应能力怎样实现，而不只是给变化换两个名字。'),('检查类比','把人造物的例子用于自然整体或终极原因时，必须说明新增前提是否成立。')],compare=[('亚里士多德','把为什么分成不同的说明层次。','自然物与人造物不能毫无区分地类比。'),('阿奎那','在新的神学论题中重用相关区分。','不等于亚里士多德已经写出基督教神学。'),('培根','批评过早用目的解释自然现象。','并非一句批评便删除所有目的性问题。')]),
 'happiness': dict(title='怎样区分短暂快感与值得过的一生？',owner='对读三种古代伦理方案；并非一份三家共同的证明',terms=[('幸福／善生活','古代伦理讨论整体生活是否过得好，含义往往大于某时某刻的愉快感受。'),('德性','使活动或选择表现良好的品格与能力；不同学派对其范围及与幸福的关系有不同论证。'),('无扰','免除心灵扰乱的状态，不表示可以不顾他人或不加审慎地追求刺激。')],steps=[('区分尺度','短时的满足不能单独决定一生的好坏，需说明评价生活所用的标准。'),('检查选择','讨论一个人怎样判断欲望、行动和关系，不能只看最后是否获得财富。'),('引入不幸','以疾病、失财或挫折检验外在条件在善生活中有多大分量。'),('比较代价','各方案处理脆弱性的方法不同，应问它们分别保留了什么、承担了什么难题。')],compare=[('亚里士多德','以合乎德性的活动理解幸福。','外在条件及运气仍有影响。'),('伊壁鸠鲁','以审慎、友谊与免除痛苦扰乱理解快乐。','不能等同于不断增加感官刺激。'),('斯多亚学派','以德性为善的核心，训练判断与行动。','不能据此说痛苦在经验上不存在。')]),
 'evil': dict(title='“恶是缺失”究竟解释了什么？',owner='以奥古斯丁式问题为例；须区分形而上学与苦难经验',terms=[('善的缺失','把恶理解为某种应有秩序或完善受到破坏，不把它设为与善对等的独立本原。'),('意志','讨论行动方向、选择与责任的能力；其自由及受损状态在不同作者处需要分别论证。'),('天意与预知','关于秩序和认识的不同问题；预先被知道是否等于被迫发生，需要独立说明。')],steps=[('限定问题','先分开道德行动的败坏、受苦经验与有限性，不用同一例子偷偷替换三者。'),('解释依存','损坏总是某个存在者的损坏，因此缺失说试图说明恶依赖于已有的善。'),('追问责任','若意志背离应有的秩序，仍要说明选择、能力与责任之间怎样相连。'),('承认剩余','这种分析不能单独解释每一场灾难为何发生于某个人，也不能取消对苦难的回应。')],compare=[('奥古斯丁','反对善恶两个对等本原，讨论意志与秩序。','不表示一切受苦都由患者个人选择造成。'),('波埃修','讨论命运、天意和预知中的自由。','认识与强迫不是未经证明就可互换的概念。'),('后世读者','用这些区分继续讨论恶与责任。','不能拿抽象答案代替对具体受害者的关怀。')]),
 'universals': dict(title='给一百个人使用同一词语，需要增加一个“普遍人”吗？',owner='围绕中世纪共相问题作分层重构',terms=[('共相','可普遍适用于许多个体的东西究竟是什么，是一组相关问题，不只是一个现成答案。'),('共同本性','说明个体具有可共同认识的性质的概念；它怎样在个体中存在，各作者并不一致。'),('个体化','说明某存在者为什么是这个独特个体，不能直接替换成心理上的个性。')],steps=[('从使用出发','同一称谓可以谈论许多个体，这一现象首先需要说明而非立刻定性。'),('拆成三层','分别讨论事物中有什么、心灵如何认识、词语在命题中如何代表对象。'),('比较设定','各方案是否需要共同本性或额外实体？这些设定解决了什么，又带来什么负担？'),('检查反驳','检验的是具体方案，不能仅凭唯实或唯名两个标签就判定立场优劣。')],compare=[('阿伯拉尔','检视共同称谓及其适用根据。','不是任意命名即可使任何分类成立。'),('邓司各脱','区分共同本性与个体化的条件。','共同本性不宜直接想象成另一个普通个体。'),('奥卡姆','以个别存在者与概念的普遍功能解释。','承认概念不等于承认事物外的普遍实体。')]),
 'faith-reason': dict(title='安瑟伦论证的争点在哪里？',owner='《宣讲》第二章论证的入门重构，不替代原文',terms=[('信仰寻求理解','从已持有的信仰中展开理解与追问，不是先保证所有推理都不会遇到异议。'),('本体论论证','后世用于称呼此类论证的名称；不能当作安瑟伦自己已经采用的学科分类。'),('自然神学','通过自然理性讨论某些关于上帝的问题，不自动意味着能推出所有启示教义。')],steps=[('界定所想','论证围绕一个特殊的关于上帝的概念展开，不是任意幻想一个很好的东西。'),('作出区分','论证区分在理解中被把握与在实在中存在，继而追问仅有前者是否足够。'),('推进反证','若只在理解中存在，就似乎还能设想一个更大的存在，因而与起初规定冲突。'),('指出争点','这种比较是否适用、概念是否可能、由此能否达到实在，正是反对者要检验的环节。')],compare=[('安瑟伦','在信仰语境中尝试一种概念论证。','从概念到实在的关键步骤仍须辩护。'),('高尼罗','以完美岛屿类比质疑推理方式。','类比是否适用于该特殊对象，也要检验。'),('阿奎那','从变化、依赖等分析推进另一类论证。','推到终极原因仍不等于证明全部教义。')]),
 'natural-law': dict(title='从一般原则到具体行动，中间缺了哪几步？',owner='以阿奎那自然法与实践判断为线索',terms=[('自然法','阿奎那法律理论中理性参与普遍秩序的实践原则，不是把所有自然现象直接变成命令。'),('实践智慧','在具体情境中判断怎样行动的能力，不只是记住抽象规则。'),('原则与规定','一般原则和具体制度规则之间有推理与安排，不能自动画等号。')],steps=[('把握原则','先说明作为实践起点的一般原则及其在整套理论中的地位。'),('理解事实','具体行动还要知道对象、处境、能力和可能后果，不能省略事实判断。'),('作出判断','检验原则如何适用于这个案例，哪些制度安排属于可变的具体化。'),('检查异议','习俗、错误和权力可能妨碍判断，所以历史上实际存在的法令不天然等于正当。')],compare=[('亚里士多德','讨论行动、品格与具体情境中的判断。','不能直接用现代法律术语覆盖其语境。'),('阿奎那','将自然法置于法律及行动的神学理论中。','普遍原则不等于每一条历史法令。'),('比较阅读者','可对读不同传统如何处理原则与情境。','主题相似不能单独证明实际传承。')]),
 'humanism': dict(title='一份文书的语言，怎样成为历史证据？',owner='以瓦拉式文本批判为例；不是所有真伪判断的通用捷径',terms=[('语文学','结合语言、文本、传本和历史处境进行理解与批判的实践，不能只等同于背单词。'),('时代错置','把不属于所声称时代的表达或制度放入其中，可能成为检验文本的重要线索。'),('人文主义教育','围绕语言、修辞、诗、历史和道德等学习实践形成多种路线，并非统一反宗教宣言。')],steps=[('核对声称','先记录文书自称的作者、年代、功能及传本，而不是由现有权威直接判定真伪。'),('寻找差异','检查语言、制度与历史条件是否符合所声称时代，区分孤立可疑点和一组相互支持的证据。'),('比较解释','考虑后改、抄误、伪托或不同形成层次，哪一种更能解释现有材料？'),('限制结论','即使否定某文书的古代身份，也不自动解决由它引出的所有制度和神学争议。')],compare=[('彼特拉克','古典阅读参与道德、自我与历史意识的塑造。','不能简化成无宗教的现代个人主义。'),('瓦拉','语言和历史分析用于检验权威文本。','不能仅靠一个孤立词语完成所有真伪判断。'),('伊拉斯谟','文本比较与注释参与基督徒改革关怀。','回到原文并不保证读者立场全部一致。')]),
 'method': dict(title='培根的经验研究为何不是随手归纳？',owner='以培根的知识改革为例，与蒙田和笛卡尔对读',terms=[('归纳','从经验材料推进一般认识的方法问题；材料安排、排除和反例处理都是关键。'),('偶像／偏见','培根用来检视妨碍认识的倾向和习惯的分类，不只是批评别人固执。'),('方法怀疑','笛卡尔主动检验信念根据的步骤，不等于对所有事情永久不作判断。')],steps=[('整理材料','研究不能只挑支持自己观点的案例，还需有次序地安排现象与差异。'),('检视偏见','语言、习惯、共同倾向及学说权威都可能影响观察和推断。'),('处理反例','不利材料应进入检验，不能在结论不顺眼时被随意排除。'),('限定成果','从材料推进解释需要进一步工作，不是有限例子一出现就自动获得确定不变的定律。')],compare=[('蒙田','以随笔检验判断、习俗与自我。','怀疑也涉及一种生活实践。'),('培根','重组经验研究和知识协作。','不是只把观察数量不断加大。'),('笛卡尔','以方法怀疑寻求稳固根据。','不是完全拒绝经验或实验。')])}
 for q in data['cultureQuestions']:
  r=rows[q['id'].removeprefix('question-')]
  q['keyTerms']=[dict(term=t,definition=d) for t,d in r['terms']]
  q['argument']=dict(title=r['title'],owner=r['owner'],steps=[dict(label=l,text=t) for l,t in r['steps']],caution='以上为编者为了阅读而重构的步骤，不是原典逐字引文，也不表示这些步骤已得到所有哲学家同意。')
  q['positions']=[dict(name=n,claim=c,limit=l) for n,c,l in r['compare']]
 data['philosophyReadingPaths']=[
  dict(id='foundations',title='从希腊的问题读起',description='先分辨知识与意见，再看共同性质、变化和善生活。',questionIds=['question-knowledge','question-forms','question-causes','question-happiness']),
  dict(id='medieval',title='进入中世纪的争论',description='从共相到信仰、恶与责任，再看实践原则如何进入行动。',questionIds=['question-universals','question-faith-reason','question-evil','question-natural-law']),
  dict(id='renaissance',title='从文艺复兴走向知识改革',description='先看古典语言和文本，再比较怀疑、归纳与知识根据。',questionIds=['question-humanism','question-method','question-knowledge'])]
